//! Every `main` vector of the BIP draft "PQB Vault Secret Management" 0.2.0
//! (`bip-qsb-wallet-secrets/vectors.json`, bips commit `bb439086`), generated by
//! pqb at commit `82c7cba`. The app serves `main` only, so the `testnet4` and
//! `regtest` children are left out, and so is the BIP 39 root (no PBKDF2 here);
//! its `main` child is covered through the vault seed alone.

use core::str::FromStr;
use std::format;
use std::string::{String, ToString};

use bitcoin::bip32::{ChildNumber, DerivationPath, Xpriv};
use bitcoin::secp256k1::Secp256k1;
use bitcoin::NetworkKind;
use sha2::Digest;

use super::support::*;
use crate::hash::soft::Soft;
use crate::pqb::{self, child_entropy, vault_seed, Curve};

fn child(root: &Xpriv, v: u32) -> ([u8; 32], [u8; 32]) {
    let secp = Secp256k1::new();
    // The app's path, which must print as the BIP's.
    let path: DerivationPath = pqb::bip85_path(v).map(ChildNumber::from).to_vec().into();
    assert_eq!(path.to_string(), format!("83696968'/39'/0'/24'/{v}'"));
    let k = root
        .derive_priv(&secp, &path)
        .unwrap()
        .private_key
        .secret_bytes();
    let e = child_entropy::<Soft>(&k);
    (e, vault_seed::<Soft>(&e))
}

fn fingerprint(root: &Xpriv) -> String {
    hex::encode(root.fingerprint(&Secp256k1::new()).as_bytes())
}

#[test]
fn bip_roots() {
    let root = Xpriv::from_str("xprv9s21ZrQH143K2LBWUUQRFXhucrQqBpKdRRxNVq2zBqsx8HVqFk2uYo8kmbaLLHRdqtQpUm98uKfu3vca1LqdGhUtyoFnCNkfmXRyPXLjbKb").unwrap();
    // BIP85 published test root
    assert_eq!(fingerprint(&root), "627ef3a6");
    let (e, s) = child(&root, 0);
    assert_eq!(
        hex::encode(e),
        "ae131e2312cdc61331542efe0d1077bac5ea803adf24b313a4f0e48e9c51f37f"
    );
    assert_eq!(
        hex::encode(s),
        "b267680d8a1a370e5b7978c725873e36ab66005e6ed25bc0f09c7607e3a2f8f3"
    );
    let (e, s) = child(&root, 1);
    assert_eq!(
        hex::encode(e),
        "29aa627357e00f09d28aa19499fc0bf06256ab389d72d7580cc450b4f2cf87e0"
    );
    assert_eq!(
        hex::encode(s),
        "0f09a6375fed8bf11513b2984e937dbe50d9e3435d8c7ef6137d07a381cf2c09"
    );
    let root = Xpriv::new_master(
        NetworkKind::Main,
        &h("000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f"),
    )
    .unwrap();
    // pqb 32-byte master seed
    assert_eq!(fingerprint(&root), "5a3469b6");
    let (e, s) = child(&root, 0);
    assert_eq!(
        hex::encode(e),
        "ac5d82e0b23b2cb37ed3bfee23bf408ad3dc877bde8f14366d89ec10d3c36e99"
    );
    assert_eq!(
        hex::encode(s),
        "2327eab6180466e3ca672f041df5daa5826b328cafd0dfb4ad32512627fbcf4f"
    );
    let (e, s) = child(&root, 2147483647);
    assert_eq!(
        hex::encode(e),
        "350df695134736ed8665ff193853540b9792dc4c7dafdad04964fcfbc9355f12"
    );
    assert_eq!(
        hex::encode(s),
        "54ab485b287ef9429bc16af6d11046ea34f2d7f82fd4a9d9183e169f4e30e60f"
    );
}

/// BIP85 published test root, index 0, main.
#[test]
fn bip_vault_0() {
    let v = vault(h32(
        "b267680d8a1a370e5b7978c725873e36ab66005e6ed25bc0f09c7607e3a2f8f3",
    ));
    assert_eq!(
        hex::encode(v.table_secret::<Soft>(0)),
        "821865a8b2c9fca47010bd308f8d9e968e708e10"
    );
    assert_eq!(
        hex::encode(v.table_round1::<Soft>(0)),
        "1f15ffcc96fa5591d991d7b00ece01044044e312414ace687931423a43e87201"
    );
    assert_eq!(
        hex::encode(v.table_commitment::<Soft>(0)),
        "3c68700e53e401eae2caa6a2f6d2441dbb8b93d7"
    );
    assert_eq!(
        hex::encode(v.table_secret::<Soft>(108)),
        "82dbf0eb9da4738266d51ba0bb613dd94aa6c2f1"
    );
    assert_eq!(
        hex::encode(v.table_round1::<Soft>(108)),
        "a6dc5db8fb64576dd99748d8a5200e24317354798d4768ce2880bf2921864e04"
    );
    assert_eq!(
        hex::encode(v.table_commitment::<Soft>(108)),
        "f77db47809c4d5ec92f5d22785dce41765503aa1"
    );
    menu(
        &v,
        0,
        0,
        "3025020101022004e59cfd520bb55b6c9da0c4bcaecd63eaa44f72de5bf78efd9c8285481ab8a001",
        "1c59a4d6ea6e90dcf86f99bc958e1776cafee841",
    );
    menu(
        &v,
        0,
        11,
        "3025020101022004bb6ba5b58afd867dc54f06134aca0d6652aa1c2226eeff067961d85a71181401",
        "1da06a047272183c65246ab2812efd09af001c38",
    );
    menu(
        &v,
        1,
        15,
        "302602020081022006aeba3a1e782170889c4d6f44f1714d20ab924c73b6052e476935033e49374601",
        "6722e537649b15c72e97456df664648781a120bb",
    );
    menu(
        &v,
        2,
        0,
        "3026020200810220071fff9da6f7f368f3bd25c64ae7b3cbff13f24f0e8f468b23676b530be04a1a01",
        "fa83c298f2f31c90b96e3a316322a1a1672c9582",
    );
    let q = SoftCurve::pubkey(&v.cosign_key::<Soft>());
    assert_eq!(
        hex::encode(q),
        "03f50b580eedf9292116f692d2a5a417e7202e049ce08f42032fabcc56cb2956c0"
    );
    assert_eq!(
        hex::encode(v.commitment::<Soft>(153)),
        "be8dda581984247d752642f1ff25921ded1507fe"
    );
    let dd = SoftCurve::pubkey(&v.deposit_key::<Soft>());
    assert_eq!(
        hex::encode(dd),
        "034a9bca360e73149495deb25c21e32dc48157f49f613a517e9d1017f339f23690"
    );
    let spk = crate::script::p2wpkh(&crate::hash::hash160::<Soft>(&dd));
    assert_eq!(
        hex::encode(spk),
        "0014cab5dd081281dedd18da8ba65a978c41a2df8b28"
    );
    let addr = crate::address::from_script::<Soft>(&spk).unwrap();
    assert_eq!(addr.as_str(), "bc1qe26a6zqjs80d6xx63wn949uvgx3dlzegvl7jeg");
    let mut len = 0;
    v.script_into::<Soft>(|b| len += b.len());
    assert_eq!(len, 4696);
    assert_eq!(
        hex::encode(v.script_hash::<Soft>()),
        "67014f1e8783b06a7f8d028d5ff02ee9534aef658838f79b92a35e9a857dd7f0"
    );
    assert!(v.screened_root::<Soft>().is_some());
    assert_eq!(
        seed_fingerprint("b267680d8a1a370e5b7978c725873e36ab66005e6ed25bc0f09c7607e3a2f8f3"),
        "25dd9c0aeea1944d"
    );
}

/// pqb 32-byte master seed, index 0, main.
